`, "",{"version":3,"sources":["webpack://./src/佩伊洛/脚本/流式楼层界面/Galgame.vue"],"names":[],"mappings":"AAyFA,+BACE,iBAAkB,CAClB,UAAW,CACX,iBAAkB,CAClB,eAAgB,CAChB,iBAAkB,CAClB,aAAc,CACd,cAAe,CACf,wBAAiB,CAAjB,gBACF,CACA,6BACE,iBAAkB,CAClB,OAAQ,CACR,yCAA0C,CAC1C,qCACF,CACA,iCACE,iBAAkB,CAClB,QAAS,CACT,QAAS,CACT,0BAA2B,CAC3B,UAAW,CACX,kBAAmB,CACnB,mBAAoB,CACpB,4BACF,CACA,mCACE,iBAAkB,CAClB,QAAS,CACT,MAAO,CACP,OAAQ,CACR,wDAA6D,CAC7D,sBAAuB,CACvB,cACF,CACA,kCACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,iBACF,CACA,iCACE,cAAe,CACf,eAAgB,CAChB,aACF,CACA,mCACE,iBAAkB,CAClB,QAAS,CACT,UAAW,CACX,cAAe,CACf,2BACF,CACA,+BACE,iBAAkB,CAClB,UAAW,CACX,UAAW,CACX,cAAe,CACf,2BAA+B,CAC/B,sCACF,CAGA,kCACE,iBAAkB,CAClB,WAAY,CACZ,SAAU,CACV,UAAW,CACX,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,cACF,CACA,iCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,gBAAiB,CACjB,iCAAqC,CACrC,sCAA0C,CAC1C,iBAAkB,CAClB,cAAe,CACf,wBAAyB,CACzB,yBACF,CACA,uCACE,iCAAqC,CACrC,kCAAsC,CACtC,yBACF,CACA,wCACE,yBACF,CACA,qCACE,aAAc,CACd,cAAe,CACf,eAAgB,CAChB,aACF,CACA,sCACE,cAAe,CACf,aAAc,CACd,eAAgB,CAChB,eAAgB,CAChB,sBAAuB,CACvB,kBACF,CAEA,0BACE,QAEE,SACF,CACA,IACE,WACF,CACF","sourcesContent":["<template>\n  <div class=\"galgame-root\" @click=\"advance\">\n    <div class=\"galgame-bg\" :style=\"{ backgroundImage: bgUrl }\"></div>\n    <img v-if=\"tachieUrl\" :src=\"tachieUrl\" class=\"galgame-tachie\" />\n    <div class=\"galgame-dialogue\">\n      <div v-if=\"current\" class=\"galgame-speaker\">{{ current.speaker }}</div>\n      <div v-if=\"current\" class=\"galgame-speech\">{{ current.speech }}</div>\n      <div class=\"galgame-progress\">{{ idx + 1 }} / {{ chats.length }}</div>\n    </div>\n    <!-- 内嵌选择框：在最后一帧时显示 -->\n    <div v-if=\"isLastFrame && options.length > 0\" class=\"galgame-choices\" @click.stop>\n      <div v-for=\"(option, i) in options\" :key=\"option.title\" class=\"galgame-choice\" @click=\"handleChoiceClick(option)\">\n        <span class=\"galgame-choice-num\">{{ circleNums[i] || `${i + 1}` }}</span>\n        <span class=\"galgame-choice-text\">{{ option.content }}</span>\n      </div>\n    </div>\n    <div v-else-if=\"idx < chats.length - 1\" class=\"galgame-hint\">点击继续</div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport YAML from 'yaml';\n\nconst CDN = 'https://testingcf.jsdelivr.net/gh/uyse44846-cmd/tavern_helper_template@main/dist/佩伊洛';\n\ninterface Chat {\n  speaker: string;\n  speech: string;\n  background: string;\n  tachie?: string;\n}\n\ninterface Option {\n  title: string;\n  content: string;\n}\n\nconst props = defineProps<{ message: string; directSend?: boolean }>();\n\nconst circleNums = ['①', '②', '③', '④', '⑤'];\n\nconst chats = ref<Chat[]>([]);\nconst idx = ref(0);\n\nconst options = ref<Option[]>(\n  (() => {\n    const text = props.message.match(/<roleplay_options>(.*?)<\\/roleplay_options>/s)?.[1] ?? '';\n    return [...text.matchAll(/(.+?)[:：]\\s*(.+)/gm)].map(m => ({\n      title: m[1],\n      content: m[2].replace(/^\\$\\{(.+)\\}$/, '$1').replace(/^「(.+)」$/, '$1'),\n    }));\n  })(),\n);\n\nonMounted(() => {\n  const yaml = props.message.match(/<galgame>\\s*```yaml\\s*([\\s\\S]*?)```\\s*<\\/galgame>/)?.[1] ?? '';\n  try {\n    chats.value = YAML.parse(yaml) ?? [];\n  } catch {\n    chats.value = [];\n  }\n});\n\nconst current = computed(() => chats.value[idx.value]);\nconst isLastFrame = computed(() => idx.value >= chats.value.length - 1);\nconst bgUrl = computed(() => {\n  if (!current.value?.background) return 'none';\n  return `url(${CDN}/背景/${current.value.background})`;\n});\nconst tachieUrl = computed(() => {\n  if (!current.value?.tachie) return '';\n  return `${CDN}/角色立绘/${current.value.tachie}`;\n});\n\nfunction advance() {\n  if (idx.value < chats.value.length - 1) idx.value++;\n}\n\nasync function handleChoiceClick(item: Option) {\n  if (props.directSend !== false) {\n    await createChatMessages([{ role: 'user', message: item.content }]);\n    triggerSlash('/trigger');\n  } else {\n    triggerSlash(`/setinput ${item.content}`);\n  }\n}\n</script>\n\n<style scoped>\n.galgame-root {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16/9;\n  overflow: hidden;\n  border-radius: 8px;\n  margin: 12px 0;\n  cursor: pointer;\n  user-select: none;\n}\n.galgame-bg {\n  position: absolute;\n  inset: 0;\n  background: center/cover no-repeat #1a1a2e;\n  transition: background-image 0.5s ease;\n}\n.galgame-tachie {\n  position: absolute;\n  bottom: 0;\n  left: 50%;\n  transform: translateX(-50%);\n  height: 85%;\n  object-fit: contain;\n  pointer-events: none;\n  transition: opacity 0.3s ease;\n}\n.galgame-dialogue {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  background: linear-gradient(transparent, rgba(0, 0, 0, 0.85));\n  padding: 40px 24px 20px;\n  min-height: 30%;\n}\n.galgame-speaker {\n  font-size: 14px;\n  font-weight: 600;\n  color: #ffb6c1;\n  margin-bottom: 6px;\n}\n.galgame-speech {\n  font-size: 15px;\n  line-height: 1.7;\n  color: #f0f0f0;\n}\n.galgame-progress {\n  position: absolute;\n  top: 12px;\n  right: 16px;\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.5);\n}\n.galgame-hint {\n  position: absolute;\n  bottom: 8px;\n  right: 16px;\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.4);\n  animation: blink 1.5s infinite;\n}\n\n/* 内嵌选择框样式 - 方案A：清新粉蓝 */\n.galgame-choices {\n  position: absolute;\n  bottom: 12px;\n  left: 16px;\n  right: 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  cursor: default;\n}\n.galgame-choice {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 14px;\n  background: rgba(255, 255, 255, 0.15);\n  border: 1px solid rgba(255, 182, 193, 0.3);\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s ease;\n  backdrop-filter: blur(8px);\n}\n.galgame-choice:hover {\n  background: rgba(255, 240, 245, 0.25);\n  border-color: rgba(255, 182, 193, 0.5);\n  transform: translateX(4px);\n}\n.galgame-choice:active {\n  transform: translateX(2px);\n}\n.galgame-choice-num {\n  color: #ffb6c1;\n  font-size: 14px;\n  font-weight: 600;\n  flex-shrink: 0;\n}\n.galgame-choice-text {\n  font-size: 13px;\n  color: #f0f0f0;\n  line-height: 1.4;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n@keyframes blink {\n  0%,\n  100% {\n    opacity: 1;\n  }\n  50% {\n    opacity: 0.3;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
